-- Removes every sample seller and listing added by seed-sample-listings.sql (2026-11-24). Generated by build.py.
-- Then remove the photos: product-images/<seller>/samples/ for each seller below (Storage objects don't cascade).
begin;
create temp table sample_ids on commit drop as
  select s.vendor_id from admin.sample_vendors s where s.vendor_id in (
  'a71cb5a5-ef71-5ff1-ba72-ff4c7a02e9dc',
  '9a64708b-9cd0-5155-8211-0b0c8c2036dd',
  '04d9d594-0bd4-5829-8d4a-c396c2ccf8fd',
  'af38d4ac-6825-5bbd-8c1a-87685385fe68',
  '5ea25e88-0b75-56d8-b084-d7d883688538',
  'f7e8a5ca-0160-535c-8c16-8c70f9034e38',
  '9d41f29b-9087-5475-821b-65f5f3827da5',
  'fd79a4e8-e65d-5f3d-8a92-1b50238a62a1',
  'd26d58a9-4303-5389-9747-a40f63e3759c',
  'f863a722-c70d-52c3-ae8a-e3022db264e0',
  'c228ce66-f7cd-5171-b273-bdb6bfdf517f',
  'e1085b0e-c1dd-5f28-a93d-4d05b55c9cc3',
  '063fe3fe-e329-584e-9c65-df6725c7ce91',
  '56cc226c-e9e8-51b1-b2b6-2babb81151e9',
  'a137d525-a734-5770-a31b-1cb322c5ff0e',
  '890ee646-6006-5ed0-971c-069a0a852272',
  'c2f74b97-49e1-5cf1-85f9-ce1638e961dc',
  '15189033-0bf6-5c52-abc9-4b859325ace5',
  '885fc36b-cbe8-5359-a830-28b248f2d1f9',
  'fcdf5a63-00f5-5397-a779-5b9587421ed5',
  'c297569b-b3f1-515f-9b75-dba60d9ee63f',
  'b153023f-556d-54af-b488-e4508a732f72',
  '228ac0df-492e-5d22-97ca-62dc16befce5',
  'b4853311-bcb2-572c-ab8b-1cd88e3dea82',
  '7bce9e94-5c7f-578e-ba0b-b3e2b31f38eb',
  '0538cb41-a6ab-5152-8d92-c5f02cc11367',
  'a91d8fdf-0baa-53ed-a73b-08305fb40d13',
  '6f8ac993-6e25-5b80-847e-8db09cb45a88');
delete from public.product_images where product_id in (select p.id from public.products p where p.vendor_id in (select vendor_id from sample_ids));
delete from public.products where vendor_id in (select vendor_id from sample_ids);
delete from admin.registration_exempt where vendor_id in (select vendor_id from sample_ids);
delete from admin.sample_vendors where vendor_id in (select vendor_id from sample_ids);
delete from public.vendor_profiles where id in (select vendor_id from sample_ids);
delete from auth.users where id in (select vendor_id from sample_ids);
commit;
